"""Generate the eval case messages (evals/cases/*.xml) from evals/golden.json. Made-up data only.

Run from the project folder: .venv/bin/python -m evals.make_cases
"""

import json
from pathlib import Path
from xml.sax.saxutils import escape

EVALS_DIR = Path(__file__).resolve().parent
GOLDEN = EVALS_DIR / "golden.json"
CASES_DIR = EVALS_DIR / "cases"

HEADER = ('<?xml version="1.0" encoding="UTF-8"?>\n'
          "<!-- GENERATED by evals/make_cases.py from golden.json; do not edit. MADE-UP TEST DATA: names are\n"
          "     placeholders, IBANs are public documentation examples, US account numbers are invented. -->\n")

# Public documentation example IBANs (valid checksums), as in samples/.
SEPA_PARTIES = {
    "SEPA_INSTANT": ("Erika Mustermann", "DE89370400440532013000", "TESTDEFFXXX",
                     "Jan Jansen", "NL91ABNA0417164300", "TESTNL2AXXX"),
    "SEPA_DD": ("Juan Perez", "ES9121000418450200051332", "TESTESMMXXX",
                "Example Fitness GmbH", "DE89370400440532013000", "TESTDEFFXXX"),
}


def _reason_block(tag: str, case: dict) -> str:
    if not case["code"]:
        return ""  # accepted or pending: no reason
    extra = f"<AddtlInf>{escape(case['injection'])}</AddtlInf>" if case.get("injection") else ""
    return f"<{tag}><Rsn><Cd>{case['code']}</Cd></Rsn>{extra}</{tag}>"


def _remittance(case: dict) -> str:
    # The injection also sits in the remittance text, where a customer can type anything.
    return f"<RmtInf><Ustrd>{escape(case['injection'])}</Ustrd></RmtInf>" if case.get("injection") else ""


def pacs002(case: dict, n: int) -> str:
    rtp = case["rail"] == "RTP"
    if rtp:
        settlement = "<SttlmInf><SttlmMtd>CLRG</SttlmMtd><ClrSys><Prtry>TCH</Prtry></ClrSys></SttlmInf>"
        payment_type = ""
        debtor = ("<Dbtr><Pty><Nm>John Q. Public</Nm></Pty></Dbtr>"
                  "<DbtrAcct><Id><Othr><Id>123456789012</Id></Othr></Id></DbtrAcct>"
                  "<DbtrAgt><FinInstnId><ClrSysMmbId><MmbId>999999991</MmbId></ClrSysMmbId></FinInstnId></DbtrAgt>")
        creditor = ("<CdtrAgt><FinInstnId><ClrSysMmbId><MmbId>999999992</MmbId></ClrSysMmbId></FinInstnId></CdtrAgt>"
                    "<Cdtr><Pty><Nm>Jane Doe</Nm></Pty></Cdtr>"
                    "<CdtrAcct><Id><Othr><Id>000987654321</Id></Othr></Id></CdtrAcct>")
        currency, amount = "USD", "480.00"
    else:
        d_name, d_iban, d_bic, c_name, c_iban, c_bic = SEPA_PARTIES["SEPA_INSTANT"]
        settlement = ""
        payment_type = "<PmtTpInf><SvcLvl><Cd>SEPA</Cd></SvcLvl><LclInstrm><Cd>INST</Cd></LclInstrm></PmtTpInf>"
        debtor = (f"<Dbtr><Pty><Nm>{d_name}</Nm></Pty></Dbtr><DbtrAcct><Id><IBAN>{d_iban}</IBAN></Id></DbtrAcct>"
                  f"<DbtrAgt><FinInstnId><BICFI>{d_bic}</BICFI></FinInstnId></DbtrAgt>")
        creditor = (f"<CdtrAgt><FinInstnId><BICFI>{c_bic}</BICFI></FinInstnId></CdtrAgt>"
                    f"<Cdtr><Pty><Nm>{c_name}</Nm></Pty></Cdtr><CdtrAcct><Id><IBAN>{c_iban}</IBAN></Id></CdtrAcct>")
        currency, amount = "EUR", "250.00"
    return HEADER + f"""<Document xmlns="urn:iso:std:iso:20022:tech:xsd:pacs.002.001.10">
  <FIToFIPmtStsRpt>
    <GrpHdr><MsgId>MSG-EVAL-{n:04}</MsgId><CreDtTm>2026-10-16T10:00:00.000+02:00</CreDtTm></GrpHdr>
    <OrgnlGrpInfAndSts><OrgnlMsgId>ORIG-EVAL-{n:04}</OrgnlMsgId><OrgnlMsgNmId>pacs.008.001.08</OrgnlMsgNmId></OrgnlGrpInfAndSts>
    <TxInfAndSts>
      <StsId>STS-EVAL-{n:04}</StsId>
      <OrgnlEndToEndId>E2E-EVAL-{n:04}</OrgnlEndToEndId>
      <TxSts>{case['status']}</TxSts>
      {_reason_block("StsRsnInf", case)}
      <OrgnlTxRef>
        <IntrBkSttlmAmt Ccy="{currency}">{amount}</IntrBkSttlmAmt>
        <IntrBkSttlmDt>2026-10-16</IntrBkSttlmDt>
        {settlement}{payment_type}{_remittance(case)}
        {debtor}
        {creditor}
      </OrgnlTxRef>
    </TxInfAndSts>
  </FIToFIPmtStsRpt>
</Document>
"""


def pacs004(case: dict, n: int) -> str:
    d_name, d_iban, d_bic, c_name, c_iban, c_bic = SEPA_PARTIES["SEPA_DD"]
    return HEADER + f"""<Document xmlns="urn:iso:std:iso:20022:tech:xsd:pacs.004.001.09">
  <PmtRtr>
    <GrpHdr><MsgId>MSG-EVAL-{n:04}</MsgId><CreDtTm>2026-10-16T07:30:00.000+02:00</CreDtTm><NbOfTxs>1</NbOfTxs>
      <SttlmInf><SttlmMtd>CLRG</SttlmMtd></SttlmInf></GrpHdr>
    <TxInf>
      <RtrId>RTR-EVAL-{n:04}</RtrId>
      <OrgnlGrpInf><OrgnlMsgId>ORIG-EVAL-{n:04}</OrgnlMsgId><OrgnlMsgNmId>pacs.003.001.08</OrgnlMsgNmId></OrgnlGrpInf>
      <OrgnlEndToEndId>E2E-EVAL-{n:04}</OrgnlEndToEndId>
      <RtrdIntrBkSttlmAmt Ccy="EUR">49.99</RtrdIntrBkSttlmAmt>
      {_reason_block("RtrRsnInf", case)}
      <OrgnlTxRef>
        <ReqdColltnDt>2026-10-12</ReqdColltnDt>
        <PmtTpInf><SvcLvl><Cd>SEPA</Cd></SvcLvl><LclInstrm><Cd>CORE</Cd></LclInstrm><SeqTp>RCUR</SeqTp></PmtTpInf>
        <MndtRltdInf><MndtId>MANDATE-EVAL-{n:04}</MndtId><DtOfSgntr>2025-01-15</DtOfSgntr></MndtRltdInf>
        <Dbtr><Pty><Nm>{d_name}</Nm></Pty></Dbtr><DbtrAcct><Id><IBAN>{d_iban}</IBAN></Id></DbtrAcct>
        <DbtrAgt><FinInstnId><BICFI>{d_bic}</BICFI></FinInstnId></DbtrAgt>
        <CdtrAgt><FinInstnId><BICFI>{c_bic}</BICFI></FinInstnId></CdtrAgt>
        <Cdtr><Pty><Nm>{c_name}</Nm></Pty></Cdtr><CdtrAcct><Id><IBAN>{c_iban}</IBAN></Id></CdtrAcct>
      </OrgnlTxRef>
    </TxInf>
  </PmtRtr>
</Document>
"""


def load_golden() -> list[dict]:
    return json.loads(GOLDEN.read_text(encoding="utf-8"))["cases"]


def case_path(case: dict) -> Path:
    return CASES_DIR / f"{case['id']}.xml"


def main() -> None:
    CASES_DIR.mkdir(exist_ok=True)
    cases = load_golden()
    for n, case in enumerate(cases, 1):
        xml = pacs004(case, n) if case["message"] == "pacs.004" else pacs002(case, n)
        case_path(case).write_text(xml, encoding="utf-8")
    print(f"wrote {len(cases)} cases to {CASES_DIR}")


if __name__ == "__main__":
    main()
